INSERT INTO public.support_faqs (id, topic, title, answer, keywords, sort_order, active, updated_by, updated_at) VALUES ('d92eb561-cd5c-4f23-9a1d-fb78e06155a1', 'CANCEL', 'Chính sách hủy đơn', 'Bạn có thể tự hủy đơn khi cửa hàng chưa xác nhận và đơn chưa thanh toán. Sau khi cửa hàng đã xác nhận, vui lòng gặp nhân viên để được hỗ trợ. Đơn đã giao cho đơn vị vận chuyển thì không thể hủy. Voucher đã dùng cho đơn bị hủy sẽ không được hoàn lại.', 'hủy,huỷ,huy,cancel', 1, true, NULL, '2026-10-19 09:37:50.948735');
INSERT INTO public.support_faqs (id, topic, title, answer, keywords, sort_order, active, updated_by, updated_at) VALUES ('cedb83f5-bd19-4b11-b50c-107c86c7157b', 'SHIPPING', 'Chính sách vận chuyển', 'Đơn được giao từ cửa hàng gần bạn nhất còn đủ hàng. Nếu một cửa hàng không đủ, đơn sẽ được chia thành nhiều phần giao từ các cửa hàng khác nhau và bạn sẽ được thông báo chi tiết từng phần. Bạn có thể theo dõi chuyến giao bằng đường link trong thông tin đơn hàng.', 'giao,ship,vận chuyển,van chuyen,bao lâu,khi nào', 2, true, NULL, '2026-10-19 09:37:50.948735');
INSERT INTO public.support_faqs (id, topic, title, answer, keywords, sort_order, active, updated_by, updated_at) VALUES ('83f33c50-b675-4e0e-9683-57d72e6e45bd', 'PAYMENT', 'Chính sách thanh toán', 'Hiện tại cửa hàng hỗ trợ thanh toán khi nhận hàng (COD): bạn thanh toán cho tài xế khi nhận hàng. Thanh toán online qua VNPay và MoMo sẽ sớm được hỗ trợ.', 'thanh toán,thanh toan,trả tiền,tra tien,cod,vnpay,momo,chuyển khoản', 3, true, NULL, '2026-10-19 09:37:50.948735');
INSERT INTO public.support_faqs (id, topic, title, answer, keywords, sort_order, active, updated_by, updated_at) VALUES ('745d61ee-10ae-412f-a44a-40e32a5d5be0', 'RETURN', 'Chính sách đổi trả', 'Cửa hàng đang cập nhật chính sách đổi trả. Vui lòng gặp nhân viên để được hỗ trợ đổi hoặc trả sản phẩm.', 'đổi,trả,doi,tra,hoàn,hoan,lỗi,size', 4, true, NULL, '2026-10-19 09:37:50.948735');
